import torch

class KVProjector(torch.nn.Module):
    '''学习把发送方 KV 映射到接收方空间，双方骨干均冻结。'''
    def __init__(self, d_src, d_dst):
        super().__init__()
        self.k_proj = torch.nn.Linear(d_src, d_dst)
        self.v_proj = torch.nn.Linear(d_src, d_dst)

    def forward(self, k_src, v_src):
        return self.k_proj(k_src), self.v_proj(v_src)

def calibration_loss(receiver, q, k_src, v_src, k_ref, v_ref, projector):
    k_hat, v_hat = projector(k_src, v_src)
    out_hat = receiver.attend(q, k_hat, v_hat)
    with torch.no_grad():
        out_ref = receiver.attend(q, k_ref, v_ref)
    return torch.nn.functional.mse_loss(out_hat, out_ref)
